 92	    // -- Orchestrator --------------------------------------------------
 93	    orchestratorStart:       function (planPath, dryRun) { return request('POST',   '/orchestrator/start',                                         { planPath: planPath, dryRun: dryRun }); },
 94	    orchestratorGetQueue:    function ()                 { return request('GET',    '/orchestrator/queue'); },
 95	    orchestratorGetRunStatus: function (slug)            { return request('GET',    '/orchestrator/run-status/' + encodeURIComponent(slug)); },
 96	    orchestratorKill:        function (id)               { return request('POST',   '/orchestrator/kill/'       + encodeURIComponent(id)); },
 97	    orchestratorDismiss:     function (id)               { return request('POST',   '/orchestrator/dismiss/'    + encodeURIComponent(id)); },
 98	
 99	    // -- Knowledge -----------------------------------------------------
100	
101	    /**
102	     * List or search knowledge insights stored in the ledger's `.knowledge/`
103	     * directory.
104	     *
105	     * Falsy or empty param values are silently omitted from the query string by
106	     * `buildQueryString` — pass `undefined` to leave a filter unset rather than
107	     * sending `?scope=undefined` to the server.
108	     *
109	     * @param {Record<string, any>|null|undefined} params - Query parameters
110	     *   (e.g. `{ scope, repository_name, category, tags, q }`).
111	     * @returns {Promise<object>} Parsed JSON response from `GET /api/knowledge`.
112	     */
113	    getKnowledge: function (params) {
114	      return request('GET', '/knowledge' + buildQueryString(params));
115	    },
116	
117	    /**
118	     * Update a knowledge insight by ID.
119	     *
120	     * `scope` and `repository_name` are merged into the request body **after**
121	     * the caller-supplied `data` object, so they always take precedence — a
122	     * caller cannot override `scope` or `repository_name` via the `data` argument.
123	     *
124	     * A falsy `repositoryName` (empty string, `null`, `undefined`) is coerced to
125	     * `undefined` before serialisation, which causes the key to be omitted from
126	     * the JSON body.  Repository names are always non-empty strings in practice, so
127	     * a name of `'0'` would be incorrectly dropped — this edge-case is a known
128	     * limitation of the `|| undefined` pattern used throughout this module.
129	     *
130	     * @param {string|number} id             - Insight ID (URI-encoded automatically).

381	    const result = await listInsights({ scope: 'repository' });
382	    const data = parseResult(result as any);
383	    expect(data).toHaveLength(1);
384	    expect(data.every((i: { scope: string }) => i.scope === 'repository')).toBe(true);
385	  });
386	});
